package com.optarena.calc;

import java.util.Map;
import org.springframework.web.bind.annotation.*;

@RestController
public class DivideController {

    @PostMapping("/divide")
    public Map<String, Double> divide(@RequestBody Map<String, Double> body) {
        double a = body.get("a");
        double b = body.get("b");
        if (b == 0) {
            throw new ArithmeticException("division by zero");
        }
        return Map.of("result", a / b);
    }
}
